import React, { useEffect, useState } from "react";
import { Container, Table, Button, Modal, Form, Image, InputGroup } from "react-bootstrap";
import AdminNavbar from "./AdminNavbar";
import axios from "axios";

function Animals() {
  const [animals, setAnimals] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [alertVisible, setAlertVisible] = useState(false);
  const [searchId, setSearchId] = useState("");

  const [formData, setFormData] = useState({
    nombre: "",
    especie: "Perro",
    edad_aprox: "",
    estado_medico: "",
    descripcion: "",
    ubicacion: "",
    estado: "disponible",
    fotoFile: null,
  });

  const [editData, setEditData] = useState({
    id_animal: null,
    nombre: "",
    especie: "Perro",
    edad_aprox: "",
    estado_medico: "",
    descripcion: "",
    ubicacion: "",
    estado: "disponible",
    fotoFile: null,
    fotoPreview: null,
  });

  const token = localStorage.getItem("token");
  const baseURL = "http://localhost:5000";

  /* =========================
     CONSULTAR ANIMALES
  ========================= */
  const fetchAnimals = async () => {
    try {
      const res = await axios.get(`${baseURL}/animals/`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setAnimals(res.data);
    } catch (error) {
      console.error(error);
      if (error.response?.status === 401) alert("Token inválido o expirado");
    }
  };

  /* =========================
     CONSULTAR ANIMAL POR ID
  ========================= */
  const fetchAnimalById = async () => {
    if (!searchId) return fetchAnimals();
    try {
      const res = await axios.get(`${baseURL}/animals/${searchId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setAnimals([res.data]);
    } catch (error) {
      console.error(error);
      alert("Animal no encontrado");
      setAnimals([]);
    }
  };

  useEffect(() => {
    fetchAnimals();
  }, []);

  /* =========================
     MANEJO DE MODALES
  ========================= */
  const openModal = () => {
    setFormData({
      nombre: "",
      especie: "Perro",
      edad_aprox: "",
      estado_medico: "",
      descripcion: "",
      ubicacion: "",
      estado: "disponible",
      fotoFile: null,
    });
    setAlertVisible(false);
    setShowModal(true);
  };

  const openEditModal = (animal) => {
    setEditData({
      id_animal: animal.id_animal,
      nombre: animal.nombre,
      especie: animal.especie,
      edad_aprox: animal.edad_aprox || "",
      estado_medico: animal.estado_medico || "",
      descripcion: animal.descripcion,
      ubicacion: animal.ubicacion || "",
      estado: animal.estado,
      fotoFile: null,
      fotoPreview: animal.fotos ? `${baseURL}/uploads/${animal.fotos}` : null,
    });
    setShowEditModal(true);
  };

  /* =========================
     MANEJO DE FORMULARIOS
  ========================= */
  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "foto" && files && files.length > 0) {
      setFormData((prev) => ({ ...prev, fotoFile: files[0] }));
    } else {
      setFormData((prev) => ({ ...prev, [name]: value }));
    }
  };

  const handleEditChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "foto" && files && files.length > 0) {
      setEditData((prev) => ({ ...prev, fotoFile: files[0], fotoPreview: URL.createObjectURL(files[0]) }));
    } else {
      setEditData((prev) => ({ ...prev, [name]: value }));
    }
  };

  /* =========================
     CREAR ANIMAL
  ========================= */
  const handleSave = async () => {
    if (!formData.nombre || !formData.especie || !formData.descripcion) {
      setAlertVisible(true);
      return;
    }

    const data = new FormData();
    for (const key in formData) {
      if (formData[key]) data.append(key, formData[key]);
    }

    try {
      await axios.post(`${baseURL}/animals/createAnimal`, data, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "multipart/form-data",
        },
      });
      setShowModal(false);
      fetchAnimals();
    } catch (error) {
      console.error(error);
      alert("Error al crear animal (415 asegurate que backend recibe FormData)");
    }
  };

  /* =========================
     EDITAR ANIMAL
  ========================= */
  const handleEditSave = async () => {
    const data = new FormData();
    for (const key in editData) {
      if (editData[key] && key !== "id_animal" && key !== "fotoPreview") {
        data.append(key, editData[key]);
      }
    }

    try {
      await axios.put(`${baseURL}/animals/updateAnimal/${editData.id_animal}`, data, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "multipart/form-data",
        },
      });
      setShowEditModal(false);
      fetchAnimals();
    } catch (error) {
      console.error(error);
      alert("Error al actualizar animal (415 asegurate que backend recibe FormData)");
    }
  };

  /* =========================
     ELIMINAR ANIMAL
  ========================= */
  const handleDelete = async (animal) => {
    if (animal.estado === "disponible") {
      alert("No se puede eliminar un animal disponible");
      return;
    }
    if (!window.confirm(`¿Eliminar a ${animal.nombre}?`)) return;

    try {
      await axios.delete(`${baseURL}/animals/deleteAnimal/${animal.id_animal}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      fetchAnimals();
    } catch (error) {
      console.error(error);
      alert("Error al eliminar animal");
    }
  };

  /* =========================
     RENDER
  ========================= */
  return (
    <>
      <AdminNavbar />
      <Container className="mt-4">
        <div className="d-flex justify-content-between mb-3">
          <h1 style={{ color: "#2364c7", fontWeight: "bold" }}>Panel de Animales</h1>
          <Button variant="success" onClick={openModal}>Agregar Animal</Button>
        </div>

        {/* BUSCADOR POR ID */}
        <InputGroup className="mb-3">
          <Form.Control
            placeholder="Buscar animal por ID"
            value={searchId}
            onChange={(e) => setSearchId(e.target.value)}
          />
          <Button variant="primary" onClick={fetchAnimalById}>Consultar</Button>
        </InputGroup>

        <Table responsive bordered hover>
          <thead>
            <tr>
              <th>Imagen</th>
              <th>Nombre</th>
              <th>Especie</th>
              <th>Edad</th>
              <th>Estado Médico</th>
              <th>Descripción</th>
              <th>Ubicación</th>
              <th>Estado</th>
              <th>Acciones</th>
            </tr>
          </thead>
          <tbody>
            {animals.map((animal) => (
              <tr key={animal.id_animal}>
                <td>
                  {animal.fotos && (
                    <Image
                      src={`${baseURL}/uploads/${animal.fotos}`}
                      alt={animal.nombre}
                      thumbnail
                      style={{ width: "100px", height: "auto" }}
                    />
                  )}
                </td>
                <td>{animal.nombre}</td>
                <td>{animal.especie}</td>
                <td>{animal.edad_aprox}</td>
                <td>{animal.estado_medico}</td>
                <td>{animal.descripcion}</td>
                <td>{animal.ubicacion}</td>
                <td>{animal.estado}</td>
                <td>
                  <Button variant="info" size="sm" className="me-2" onClick={() => openEditModal(animal)}>Editar</Button>
                  <Button variant="danger" size="sm" onClick={() => handleDelete(animal)}>Eliminar</Button>
                </td>
              </tr>
            ))}
          </tbody>
        </Table>

        {/* MODAL CREAR */}
        <Modal show={showModal} onHide={() => setShowModal(false)} centered>
          <Modal.Header closeButton>
            <Modal.Title>Agregar Animal</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            {alertVisible && <div className="alert alert-danger">Por favor llena todos los campos requeridos</div>}
            <Form.Group className="mb-2">
              <Form.Label>Nombre</Form.Label>
              <Form.Control name="nombre" value={formData.nombre} onChange={handleChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Especie</Form.Label>
              <Form.Select name="especie" value={formData.especie} onChange={handleChange}>
                <option>Perro</option>
                <option>Gato</option>
              </Form.Select>
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Edad aproximada</Form.Label>
              <Form.Control name="edad_aprox" value={formData.edad_aprox} onChange={handleChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Estado médico</Form.Label>
              <Form.Control name="estado_medico" value={formData.estado_medico} onChange={handleChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Descripción</Form.Label>
              <Form.Control as="textarea" rows={3} name="descripcion" value={formData.descripcion} onChange={handleChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Ubicación</Form.Label>
              <Form.Control name="ubicacion" value={formData.ubicacion} onChange={handleChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Estado</Form.Label>
              <Form.Select name="estado" value={formData.estado} onChange={handleChange}>
                <option>disponible</option>
                <option>adoptado</option>
                <option>en_tratamiento</option>
              </Form.Select>
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Foto</Form.Label>
              <Form.Control type="file" name="foto" accept="image/*" onChange={handleChange} />
              {formData.fotoFile && <Image src={URL.createObjectURL(formData.fotoFile)} alt="Preview" thumbnail className="mt-2" style={{ width: "100px", height: "auto" }} />}
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={() => setShowModal(false)}>Cancelar</Button>
            <Button variant="primary" onClick={handleSave}>Guardar</Button>
          </Modal.Footer>
        </Modal>

        {/* MODAL EDITAR */}
        <Modal show={showEditModal} onHide={() => setShowEditModal(false)} centered>
          <Modal.Header closeButton>
            <Modal.Title>Editar Animal</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            <Form.Group className="mb-2">
              <Form.Label>Nombre</Form.Label>
              <Form.Control name="nombre" value={editData.nombre} onChange={handleEditChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Especie</Form.Label>
              <Form.Select name="especie" value={editData.especie} onChange={handleEditChange}>
                <option>Perro</option>
                <option>Gato</option>
              </Form.Select>
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Edad aproximada</Form.Label>
              <Form.Control name="edad_aprox" value={editData.edad_aprox} onChange={handleEditChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Estado médico</Form.Label>
              <Form.Control name="estado_medico" value={editData.estado_medico} onChange={handleEditChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Descripción</Form.Label>
              <Form.Control as="textarea" rows={3} name="descripcion" value={editData.descripcion} onChange={handleEditChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Ubicación</Form.Label>
              <Form.Control name="ubicacion" value={editData.ubicacion} onChange={handleEditChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Estado</Form.Label>
              <Form.Select name="estado" value={editData.estado} onChange={handleEditChange}>
                <option>disponible</option>
                <option>adoptado</option>
                <option>en_tratamiento</option>
              </Form.Select>
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Foto</Form.Label>
              <Form.Control type="file" name="foto" accept="image/*" onChange={handleEditChange} />
              {editData.fotoPreview && <Image src={editData.fotoPreview} alt="Preview" thumbnail className="mt-2" style={{ width: "100px", height: "auto" }} />}
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={() => setShowEditModal(false)}>Cancelar</Button>
            <Button variant="primary" onClick={handleEditSave}>Guardar cambios</Button>
          </Modal.Footer>
        </Modal>
      </Container>
    </>
  );
}

export default Animals;
